def calculate_min_product(m):
    """
    Calculates the minimum possible product (1/ (m+1)) for m distinct integers a_i >= 2.
    This occurs when a_i = i+1, i=1..m.
    """
    if m < 1:
        return 0
    return 1.0 / (m + 1)

target_P = 7 / 335

m4_min = calculate_min_product(4)
m5_min = calculate_min_product(5)

print(f"Target Product (7/335): {target_P}")
print(f"Minimum Product for m=4 (1/5): {m4_min}")
print(f"Minimum Product for m=5 (1/6): {m5_min}")

