def check_single_change(k, target_R_num, target_R_den):
    # We need (b_k - 1)/b_k * (k+1)/k = R_num / R_den
    # b_k = (R_num * k * (k+1)) / (R_den * (k+1) - R_num * k)
    # Wait, let's use the derived formula directly:
    # b_k = 335 * (k+1) / (335 - k)

    numerator = 335 * (k + 1)
    denominator = 335 - k

    if denominator <= 0:
        return None

    if numerator % denominator == 0:
        b_k = numerator // denominator
        # Check if b_k is distinct and positive
        if b_k >= 2 and b_k != k + 1:
            return b_k
    return None

k_values = range(1, 48)
solutions = {}

for k in k_values:
    b_k = check_single_change(k, 336, 335)
    if b_k is not None:
        solutions[k] = b_k

print("Found solutions for single term change:")
for k, b_k in solutions.items():
    print(f"k={k}: Change a_{k+1} from {k+1} to {b_k}")

